 8	/**
 9	 * Immutable compiled representation of a pattern for Knuth-Morris-Pratt searches.
10	 */
11	public final class KmpPattern {
12	    private final String value;
13	    private final int[] longestPrefixSuffix;
14	
15	    private KmpPattern(String value, int[] longestPrefixSuffix) {
16	        this.value = value;
17	        this.longestPrefixSuffix = longestPrefixSuffix;
18	    }
19	
20	    public static KmpPattern compile(CharSequence pattern) {
21	        Objects.requireNonNull(pattern, "pattern must not be null");
22	
23	        String patternValue = pattern.toString();
24	        if (patternValue.isEmpty()) {
25	            throw new IllegalArgumentException("pattern must not be empty");
26	        }
27	
28	        return new KmpPattern(patternValue, buildLongestPrefixSuffixTable(patternValue));
29	    }
30	
31	    public String value() {
32	        return value;
33	    }
34	
35	    public KmpMatcher matcher(CharSequence text) {
36	        return new KmpMatcher(this, text);
37	    }
38	
39	    public KmpMatchResult analyzeIn(CharSequence text) {
40	        return matcher(text).analyze();
41	    }
42	
43	    public List<Integer> findMatchesIn(CharSequence text) {
44	        return matcher(text).findMatches();
45	    }
46	
47	    public OptionalInt findFirstIn(CharSequence text) {
48	        return matcher(text).findFirst();
49	    }
50	
51	    public int countMatchesIn(CharSequence text) {
52	        return matcher(text).countMatches();
53	    }
54	
55	    public boolean occursIn(CharSequence text) {
56	        return matcher(text).contains();
57	    }
58	
59	    public void forEachMatchIn(CharSequence text, IntConsumer matchConsumer) {
60	        matcher(text).forEachMatch(matchConsumer);
61	    }
62	
63	    public KmpMatchIterator matchIteratorIn(CharSequence text) {
64	        return matcher(text).matchIterator();
65	    }
66	
67	    static int[] buildLongestPrefixSuffixTable(String pattern) {
68	        int[] table = new int[pattern.length()];
69	        int prefixLength = 0;
70	        int currentIndex = 1;
71	
72	        while (currentIndex < pattern.length()) {
73	            if (pattern.charAt(currentIndex) == pattern.charAt(prefixLength)) {
74	                table[currentIndex] = ++prefixLength;
75	                currentIndex++;
76	                continue;
77	            }
78	
79	            if (prefixLength > 0) {
80	                prefixLength = table[prefixLength - 1];
81	            } else {
82	                table[currentIndex] = 0;
83	                currentIndex++;
84	            }
85	        }
86	
87	        return table;
88	    }
89	
90	    KmpMatchIterator newMatchIterator(CharSequence text) {
91	        Objects.requireNonNull(text, "text must not be null");
92	        return new KmpMatchIterator(value, longestPrefixSuffix, text);
93	    }
94	}

